import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const names=['portable-runtime.mjs','pipeline.mjs','native-adapters.mjs','host-bridge.mjs','archive-closure.mjs','network-stage.mjs'];
const source=await Promise.all(names.map(x=>readFile(new URL(x,import.meta.url),'utf8')));
const hash=createHash('sha256').update(source.join('\n')).digest('hex');
const transformed=source.map(x=>x.replace(/^import .*;\n/gm,'').replace(/^export /gm,''));
const code=transformed[0]+'\nconst {TextEncoder,TextDecoder,crypto,atob,btoa}=createPortableRuntime(entropyBase64);\n'+transformed.slice(1).join('\n');
await writeFile(new URL('work.bundle.js',import.meta.url),`"use strict";\n// Generated by build-bundle.mjs; source SHA256 ${hash}\n${code}\nreturn Object.freeze({WORK_VERSION,WorkFailure,workHash,workJSON,workUnbase64,runLeadPipeline,verifyRemoteRun,evaluateWatchdog,renderLeadReport,workToolValue,createNativeAdapters,createFrozenClassifier,createWorkHostBridge,CLOSURE_VERSION,closeWorkArchive,NETWORK_STAGE_VERSION,createNetworkStageHost,createNetworkAnalyzer});\n`);
process.stdout.write(JSON.stringify({status:'built',source_sha256:hash})+'\n');
